-- 水の戸線（tokyo-mizunoto）の区間データ。tools/road.py build data/roads/tokyo-mizunoto.json で生成。手で編集しない。
-- schema.sql を実行したあとに、SQL Editor で全文を実行する。何度実行しても同じ状態になる。
-- 出典：線：© OpenStreetMap contributors（ODbL）
-- 出典：通行可否と規制：東京都森林事務所「森林事務所管理林道の通行規制について」通行状況一覧（令和8年10月2日現在）。「通行規制」は林業関係者以外の車両の乗り入れを規制。data/sources/tokyo-forestry-2026-10-02.tsv

set search_path = public, extensions;

insert into administrators (name, kind) values ('東京都森林事務所 秋川林務出張所', '都')
on conflict (name) do nothing;
insert into roads (name, kind) values ('水の戸線', '林道')
on conflict (name) do nothing;

delete from segments where road_id = (select id from roads where name = '水の戸線');

-- 檜原村：特になし（約1.2km）
insert into segments (road_id, administrator_id, surface, difficulty, general_access, note, geom)
select r.id, a.id, null, null, '可', '檜原村：特になし',
  ST_SetSRID(ST_GeomFromGeoJSON('{"type":"LineString","coordinates":[[139.1038903,35.7560357],[139.1039657,35.7559602],[139.104027,35.7559245],[139.1043706,35.7557342],[139.1049281,35.7555694],[139.1052354,35.7553979],[139.1053988,35.7552874],[139.1055673,35.7551797],[139.1056647,35.7551262],[139.105794,35.755122],[139.105974,35.755111],[139.106333,35.755173],[139.1065511,35.7552482],[139.1067016,35.7552833],[139.1068393,35.7552766],[139.1071136,35.7551686],[139.1073679,35.7549464],[139.1074873,35.7548679],[139.1075172,35.7548477],[139.1076104,35.7547847],[139.1079291,35.7545258],[139.1079963,35.7544039],[139.1080152,35.7543696],[139.1080718,35.7543071],[139.1082099,35.7542083],[139.1082466,35.7541572],[139.1083604,35.7539632],[139.1084294,35.7537654],[139.1085449,35.7534051],[139.1086308,35.7533222],[139.1087884,35.7533009],[139.1089334,35.7533199],[139.1090882,35.7532796],[139.1092222,35.7532028],[139.109353,35.753122],[139.109436,35.753111],[139.1096673,35.7530224],[139.1102597,35.7529731],[139.110506,35.752998],[139.1106485,35.753037],[139.1108203,35.7530222],[139.1109704,35.7530182],[139.1112532,35.7530245],[139.1115698,35.7529057],[139.1116876,35.7528108],[139.11185,35.7525789],[139.1119452,35.7523383],[139.1120431,35.752227],[139.1122241,35.752113],[139.1123696,35.7520625],[139.112565,35.752035],[139.1127765,35.7519552],[139.112991,35.751911],[139.113357,35.751943],[139.1138241,35.7519699],[139.1139992,35.7521081],[139.1141313,35.7521505],[139.1142172,35.752148],[139.1144025,35.752091],[139.1146344,35.7520224]]}'), 4326)
from roads r, administrators a
where r.name = '水の戸線' and a.name = '東京都森林事務所 秋川林務出張所';

-- 確認：この林道の区間と規制の数
select s.note as 区間, count(x.id) as 規制数
from segments s join roads r on r.id = s.road_id left join restrictions x on x.segment_id = s.id
where r.name = '水の戸線' group by s.id, s.note order by s.id;
